import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin, uniqueName } from './helpers';

test.describe(`incident commander: update an incident's status and assign it to a teammate`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after the commander changes status or assignee, all viewers of that incident see the update within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);
      await inviteAndJoin(pageA, pageB);

      const title = uniqueName('incident');
      await pageA.getByTestId('field-title').fill(title);
      await pageA.getByTestId('field-description').fill('500s on checkout API');
      await pageA.getByTestId('field-severity').selectOption('Critical');
      await pageA.getByTestId('field-affected_area').fill('Payments');
      await pageA.getByTestId('action-create_incident').click();

      // Commander (A) opens the incident detail view.
      await pageA.locator('[data-testid^="item-incident-"]').filter({ hasText: title }).click();
      await expect(pageA.getByTestId('field-status')).toBeVisible();

      // Viewer (B) opens the same incident once it has synced.
      await expect(
        pageB.locator('[data-testid^="item-incident-"]').filter({ hasText: title }),
      ).toBeVisible({ timeout: 5_000 });
      await pageB.locator('[data-testid^="item-incident-"]').filter({ hasText: title }).click();
      await expect(pageB.getByTestId('field-status')).toBeVisible();

      // Commander changes status.
      await pageA.getByTestId('field-status').selectOption('Investigating');
      await pageA.getByTestId('action-update_status').click();

      // Viewer sees the status update within 5s.
      await expect(pageB.getByTestId('field-status')).toHaveValue('Investigating', { timeout: 5_000 });

      // Commander assigns the incident to themself (a concrete teammate identity).
      await pageA.getByTestId('field-assigned_to').selectOption({ label: 'You' });
      await pageA.getByTestId('action-assign_incident').click();

      // Viewer sees the assignee update within 5s.
      await expect(pageB.getByTestId('field-assigned_to')).not.toHaveValue('', { timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test(`every status change is recorded in the incident's timeline with a timestamp`, async ({ page }) => {
    const title = uniqueName('incident');
    await page.getByTestId('field-title').fill(title);
    await page.getByTestId('field-description').fill('500s on checkout API');
    await page.getByTestId('field-severity').selectOption('Critical');
    await page.getByTestId('field-affected_area').fill('Payments');
    await page.getByTestId('action-create_incident').click();

    await page.locator('[data-testid^="item-incident-"]').filter({ hasText: title }).click();

    // Freshly reported: exactly one timeline entry ("Reported"), no status
    // change recorded yet.
    await expect(page.locator('.status')).toHaveCount(1);

    await page.getByTestId('field-status').selectOption('Investigating');
    await page.getByTestId('action-update_status').click();

    // The status change is appended to the timeline with its own timestamp.
    const statusEntries = page.locator('.status');
    await expect(statusEntries).toHaveCount(2, { timeout: 5_000 });
    await expect(statusEntries.nth(1)).toHaveText('Investigating');
    await expect(page.locator('time').nth(1)).not.toHaveText('');
  });
});
